from rich.repr import rich_repr

class EqualToEmpty:
    def __eq__(self, other):
        return True

@rich_repr
class MyClass:
    def __init__(self, a=EqualToEmpty()):
        self.a = a

obj = MyClass()
# If the bug exists, it will use 'getattr(self, "a")' instead of 
# yielding ("a", getattr(self, "a"), EqualToEmpty()) because
# param.default == param.empty will be True.

# Let's see what auto_rich_repr yields.
# Since rich_repr adds __rich_repr__ to the class:
for item in obj.__rich_repr__():
    print(f"Yielded: {item}")

# Expected if bug is fixed: ('a', obj.a, EqualToEmpty())
# Actual if bug exists: obj.a
